import React, { useState } from 'react';
import { Button, TextField, MenuItem, Checkbox, FormControlLabel, Typography, Box, InputLabel, Select, FormControl } from '@mui/material';

const workTypes = [
  'Maid',
  'Baby care',
  'Cook',
  'Driver',
  'Patient care',
  'Bathroom cleaning',
  'Other',
];


const startTimes = [
  '5:00 AM','6:00 AM', '7:00 AM', '8:00 AM', '9:00 AM', '10:00 AM', '11:00 AM', '12:00 PM',
  '1:00 PM', '2:00 PM', '3:00 PM', '4:00 PM', '5:00 PM', '6:00 PM', '7:00 PM', '8:00 PM', '9:00 PM',
];
const endTimes = [
  '6:00 AM','7:00 AM', '8:00 AM', '9:00 AM', '10:00 AM', '11:00 AM', '12:00 PM',
  '1:00 PM', '2:00 PM', '3:00 PM', '4:00 PM', '5:00 PM', '6:00 PM', '7:00 PM', '8:00 PM', '9:00 PM',
  '10:00 PM', '11:00 PM', '24 hours',
];


function MaidForm({ onBack }) {
  const [form, setForm] = useState({
    name: '',
    phone: '',
    workType: [],
  startTime: '5:00 AM',
  endTime: '6:00 AM',
    location: '',
    anywhere: false,
    photo: null,
  });
  const [customStart, setCustomStart] = useState(false);
  const [customEnd, setCustomEnd] = useState(false);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleCustomStart = (e) => {
    setCustomStart(true);
    setForm((prev) => ({ ...prev, startTime: e.target.value }));
  };
  const handleCustomEnd = (e) => {
    setCustomEnd(true);
    setForm((prev) => ({ ...prev, endTime: e.target.value }));
  };

  const handleWorkTypeChange = (e) => {
    setForm((prev) => ({ ...prev, workType: e.target.value }));
  };

  const handlePhoto = (e) => {
    setForm((prev) => ({ ...prev, photo: e.target.files[0] }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('name', form.name);
    formData.append('phone', form.phone);
  formData.append('workType', form.workType.join(','));
  formData.append('time', `${form.startTime} - ${form.endTime}`);
    formData.append('location', form.location);
    formData.append('anywhere', form.anywhere ? 1 : 0);
    if (form.photo) {
      formData.append('photo', form.photo);
    }
    try {
  const response = await fetch('http://localhost:5000/api/maids', {
        method: 'POST',
        body: formData
      });
      const result = await response.json();
      if (result.status === 'success') {
        alert('Registration successful!');
        setForm({
          name: '',
          phone: '',
          workType: [],
          availability: '',
          startTime: '7:00 AM',
          endTime: '8:00 AM',
          location: '',
          anywhere: false,
          photo: null,
        });
      } else {
        alert('Registration failed.');
      }
    } catch (error) {
      alert('Error submitting form.');
      console.error(error);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Typography variant="h6" gutterBottom>Maid Registration</Typography>
      <TextField label="Name" name="name" value={form.name} onChange={handleChange} fullWidth margin="normal" required />
      <TextField label="Phone number" name="phone" value={form.phone} onChange={handleChange} fullWidth margin="normal" required />
      <FormControl fullWidth margin="normal">
        <InputLabel>Type of work</InputLabel>
        <Select
          multiple
          value={form.workType}
          onChange={handleWorkTypeChange}
          renderValue={(selected) => selected.join(', ')}
        >
          {workTypes.map((type) => (
            <MenuItem key={type} value={type}>
              <Checkbox checked={form.workType.indexOf(type) > -1} />
              {type}
            </MenuItem>
          ))}
        </Select>
      </FormControl>
      <Box display="flex" gap={2} marginY={2}>
        <FormControl fullWidth>
          <InputLabel>Available Start Time</InputLabel>
          <Select
            name="startTime"
            value={form.startTime}
            onChange={handleChange}
          >
            {startTimes.map((option) => (
              <MenuItem key={option} value={option}>{option}</MenuItem>
            ))}
          </Select>
        </FormControl>
        <FormControl fullWidth>
          <InputLabel>Available End Time</InputLabel>
          <Select
            name="endTime"
            value={form.endTime}
            onChange={handleChange}
          >
            {endTimes.map((option) => (
              <MenuItem key={option} value={option}>{option}</MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>
      <TextField label="Preferred location" name="location" value={form.location} onChange={handleChange} fullWidth margin="normal" />
      <FormControlLabel
        control={<Checkbox name="anywhere" checked={form.anywhere} onChange={handleChange} />}
        label="Anywhere"
      />
      <Box marginY={2}>
        <label htmlFor="photo-upload">
          <Button variant="outlined" component="span">
            Upload photo
          </Button>
        </label>
        <input
          id="photo-upload"
          type="file"
          accept="image/*"
          onChange={handlePhoto}
          style={{ display: 'none' }}
        />
      </Box>
      <Button variant="contained" color="primary" type="submit" fullWidth>Submit</Button>
      <Button onClick={onBack} fullWidth style={{ marginTop: 8 }}>Back</Button>
    </form>
  );
}

export default MaidForm;
